@@ DEPOIS
function ordenar(botao){
  var th = botao.closest('th');
  var novo = th.getAttribute('aria-sort') === 'ascending' ? 'descending' : 'ascending';
  th.parentElement.querySelectorAll('th').forEach(function (c) {
    c.setAttribute('aria-sort', 'none');
    var s = c.querySelector('.seta');
    if (s) s.textContent = '⇅';
  });
  th.setAttribute('aria-sort', novo);
  var seta = th.querySelector('.seta');
  if (seta) seta.textContent = novo === 'ascending' ? '▲' : '▼';
}
document.querySelectorAll('.ord').forEach(function (b) {
  b.addEventListener('click', function () { ordenar(b); });
});
@@ FIM

