var live = document.getElementById('live');
var gatilhoModal = null;
var appAtual = null;

function anunciar(msg) {
  live.textContent = '';
  setTimeout(function () { live.textContent = msg; }, 50);
}

function modalAberto() {
  return document.querySelector('[data-modal]:not([hidden])');
}

function abrirModal(fundo, gatilho) {
  gatilhoModal = gatilho;
  fundo.hidden = false;
  var cancelar = fundo.querySelector('[data-fechar]');
  if (cancelar) cancelar.focus();
}

function fecharModal(fundo) {
  fundo.hidden = true;
  if (gatilhoModal && document.contains(gatilhoModal)) gatilhoModal.focus();
  gatilhoModal = null;
}

document.querySelectorAll('[data-abrir]').forEach(function (b) {
  b.addEventListener('click', function () {
    appAtual = b.getAttribute('data-app');
    if (appAtual) {
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + appAtual + '?';
    }
    abrirModal(document.getElementById(b.getAttribute('data-abrir')), b);
  });
});

document.querySelectorAll('[data-fechar]').forEach(function (b) {
  b.addEventListener('click', function () { fecharModal(b.closest('[data-modal]')); });
});

document.querySelectorAll('[data-confirmar]').forEach(function (b) {
  b.addEventListener('click', function () {
    var tipo = b.getAttribute('data-confirmar');
    if (tipo === 'revogar') anunciar('Acesso de ' + appAtual + ' revogado.');
    if (tipo === 'excluir') anunciar('Solicitação de exclusão da conta registrada.');
    fecharModal(b.closest('[data-modal]'));
  });
});

document.addEventListener('keydown', function (e) {
  var fundo = modalAberto();
  if (!fundo) return;
  if (e.key === 'Escape') { fecharModal(fundo); return; }
  if (e.key === 'Tab') {
    var itens = fundo.querySelectorAll('button:not([disabled])');
    var primeiro = itens[0];
    var ultimo = itens[itens.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  }
});

document.getElementById('btn-dispensar').addEventListener('click', function () {
  document.getElementById('banner-sucesso').hidden = true;
  var titulo = document.getElementById('h-pref');
  titulo.setAttribute('tabindex', '-1');
  titulo.focus();
});

document.getElementById('form-prefs').addEventListener('submit', function (e) {
  e.preventDefault();
  var hora = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
  document.getElementById('texto-sucesso').textContent = 'Suas preferências de notificação foram salvas às ' + hora + '.';
  document.getElementById('banner-sucesso').hidden = false;
  anunciar('Preferências salvas.');
});

document.getElementById('form-perfil').addEventListener('submit', function (e) {
  if (document.querySelector('#form-perfil [aria-invalid="true"]')) {
    e.preventDefault();
    document.getElementById('resumo-erros').focus();
    anunciar('Corrija os campos destacados para salvar o perfil.');
  }
});

