(function () {
  var live = document.getElementById('live');
  var gatilho = null;
  var tabelaAcessos = document.querySelector('#acessos table');
  var contagem = document.getElementById('contagem-acessos');
  var descRevogar = document.getElementById('dlg-revogar-d');
  var formPerfil = document.getElementById('form-perfil');
  var resumo = document.getElementById('resumo-erros');

  function focaveis(f) {
    return Array.prototype.slice.call(f.querySelectorAll('button:not([disabled]), a[href], input, select, textarea'))
      .filter(function (el) { return el.offsetParent !== null; });
  }

  function abrir(id, origem) {
    var f = document.getElementById(id);
    gatilho = origem;
    if (id === 'fundo-revogar') {
      var app = origem.closest('tr').querySelector('th').textContent;
      descRevogar.textContent = 'O aplicativo ' + app + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
    }
    f.hidden = false;
    (f.querySelector('[data-inicial]') || focaveis(f)[0]).focus();
  }

  function fechar(f) {
    f.hidden = true;
    var alvo = gatilho && gatilho.isConnected ? gatilho : document.getElementById('h-acessos');
    gatilho = null;
    alvo.focus();
  }

  document.addEventListener('keydown', function (e) {
    var aberto = document.querySelector('[data-modal]:not([hidden])');
    if (!aberto) return;
    if (e.key === 'Escape') { fechar(aberto); return; }
    if (e.key !== 'Tab') return;
    var els = focaveis(aberto);
    var primeiro = els[0], ultimo = els[els.length - 1];
    if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
    else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
  });

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });

  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () {
      var f = b.closest('[data-modal]');
      if (b.hasAttribute('data-confirmar') && gatilho) {
        gatilho.closest('tr').remove();
        var n = tabelaAcessos.querySelectorAll('tbody tr').length;
        contagem.textContent = n + (n === 1 ? ' aplicativo' : ' aplicativos') + ' com acesso à sua conta';
        live.textContent = 'Acesso revogado.';
        gatilho = null;
      }
      fechar(f);
    });
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    document.getElementById('h-pref').focus();
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    document.getElementById('banner-txt').textContent = 'Suas preferências de notificação foram salvas às ' +
      new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) + '.';
    document.getElementById('banner-sucesso').hidden = false;
    live.textContent = 'Preferências salvas.';
  });

  formPerfil.addEventListener('submit', function (e) {
    e.preventDefault();
    formPerfil.querySelectorAll('input, select, textarea').forEach(function (c) {
      var valido = c.checkValidity();
      var campo = c.closest('.campo');
      c.setAttribute('aria-invalid', valido ? 'false' : 'true');
      if (campo) {
        campo.classList.toggle('campo-erro', !valido);
        var erro = campo.querySelector('.erro');
        if (erro) erro.hidden = valido;
      }
    });
    if (!formPerfil.checkValidity()) {
      resumo.hidden = false;
      resumo.focus();
      return;
    }
    resumo.hidden = true;
    live.textContent = 'Perfil salvo.';
  });
})();
