    if (b.getAttribute('data-abrir') === 'fundo-revogar') {
      b.setAttribute('aria-label', 'Revogar acesso de ' + app);
      b.setAttribute('data-app', app);
    } else if (b.textContent.trim() === 'Encerrar sessão') {
      b.setAttribute('aria-label', 'Encerrar sessão de ' + app);
    }
  });

  function abrir(id, origem) {
    ultimoFoco = origem || document.activeElement;
    var modal = document.getElementById(id);
    if (id === 'fundo-revogar') {
      document.getElementById('dlg-revogar-d').textContent =
        'O aplicativo ' + origem.getAttribute('data-app') + ' deixará de acessar sua conta imediatamente. Você poderá autorizá-lo novamente depois.';
    }
    modal.hidden = false;
    var alvo = modal.querySelector('input') || modal.querySelector('[data-inicial]');
