    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (modal) {
    modal.addEventListener('click', function (e) { if (e.target === modal) fechar(modal); });
    modal.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fechar(modal); return; }
      if (e.key !== 'Tab') return;
      var itens = modal.querySelectorAll('button:not([disabled]), input');
      var primeiro = itens[0];
      var ultimo = itens[itens.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });

  campoExc.addEventListener('input', function () {
    btnExc.disabled = campoExc.value.trim() !== 'EXCLUIR';
