<script>
(function () {
  var ultimoOrigem = null;
  var seletorFocavel = 'a[href],button:not([disabled]),input:not([disabled]),select,textarea,[tabindex="0"]';

  function focaveis(el) {
    return Array.prototype.slice.call(el.querySelectorAll(seletorFocavel)).filter(function (f) {
      return f.offsetParent !== null;
    });
  }

  function abrirModal(modal, origem) {
    ultimoOrigem = origem;
    modal.hidden = false;
    var f = focaveis(modal);
    if (f.length) f[0].focus();
  }

  function fecharModal(modal) {
    modal.hidden = true;
    if (ultimoOrigem) {
      ultimoOrigem.focus();
      ultimoOrigem = null;
    }
  }

  document.querySelectorAll('[data-abre]').forEach(function (b) {
    b.addEventListener('click', function () {
      abrirModal(document.getElementById(b.getAttribute('data-abre')), b);
    });
  });

  document.querySelectorAll('.modal').forEach(function (m) {
    m.addEventListener('click', function (e) {
      if (e.target === m || e.target.closest('.modal-x, [data-fecha]')) fecharModal(m);
    });
    m.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fecharModal(m); return; }
      if (e.key !== 'Tab') return;
      var f = focaveis(m);
      if (!f.length) return;
      var primeiro = f[0];
      var ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) {
        e.preventDefault();
        ultimo.focus();
      } else if (!e.shiftKey && document.activeElement === ultimo) {
        e.preventDefault();
        primeiro.focus();
      }
    });
  });

  var btnAjuda = document.getElementById('btn-ajuda');
  var gaveta = document.getElementById('gaveta');

  function alternarGaveta(abrir) {
    gaveta.classList.toggle('aberta', abrir);
    btnAjuda.setAttribute('aria-expanded', String(abrir));
  }

  btnAjuda.addEventListener('click', function () {
    var abrir = !gaveta.classList.contains('aberta');
    alternarGaveta(abrir);
    if (abrir) {
      var primeiroLink = gaveta.querySelector('a');
      if (primeiroLink) primeiroLink.focus();
    } else {
      btnAjuda.focus();
    }
  });

  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && gaveta.classList.contains('aberta')) {
      alternarGaveta(false);
      btnAjuda.focus();
    }
  });

  document.querySelectorAll('[data-dispensa]').forEach(function (b) {
    b.addEventListener('click', function () {
      b.closest('.banner').remove();
      document.getElementById('conteudo').focus();
    });
  });
})();
</script>
</body>
