(function () {
  var live = document.getElementById('live');
  var gatilhoModal = null;

  function anunciar(msg) {
    live.textContent = '';
    setTimeout(function () { live.textContent = msg; }, 50);
  }

  function abrirModal(id, gatilho) {
    var m = document.getElementById(id);
    gatilhoModal = gatilho || null;
    if (id === 'fundo-revogar' && gatilho) {
      var app = gatilho.closest('tr').querySelector('th').textContent.trim();
      document.getElementById('dlg-revogar-t').textContent = 'Revogar o acesso de ' + app + '?';
    }
    m.hidden = false;
    var foco = m.querySelector('[autofocus]') || m.querySelector('button, input');
    if (foco) foco.focus();
  }

  function fecharModal(m) {
    m.hidden = true;
    if (gatilhoModal) gatilhoModal.focus();
    gatilhoModal = null;
  }

  document.querySelectorAll('tbody button').forEach(function (b) {
    var app = b.closest('tr').querySelector('th').textContent.trim();
    b.setAttribute('aria-label', b.textContent.trim() + ': ' + app);
  });

  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrirModal(b.getAttribute('data-abrir'), b); });
  });

  document.querySelectorAll('[data-modal]').forEach(function (m) {
    m.addEventListener('click', function (e) { if (e.target === m) fecharModal(m); });
    m.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fecharModal(m); return; }
      if (e.key !== 'Tab') return;
      var f = m.querySelectorAll('button, input, a[href]');
      var primeiro = f[0], ultimo = f[f.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
    m.querySelectorAll('[data-fechar]').forEach(function (b) {
      b.addEventListener('click', function () { fecharModal(m); });
    });
  });

  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
  });

  function validar(input, erroEl, msg) {
    var campo = input.closest('.campo');
    if (msg) {
      erroEl.innerHTML = '<span class="sr-only">Erro: </span>' + msg;
      erroEl.hidden = false;
      input.setAttribute('aria-invalid', 'true');
      campo.classList.add('ativo');
    } else {
      erroEl.hidden = true;
      input.removeAttribute('aria-invalid');
      campo.classList.remove('ativo');
    }
    return !msg;
  }

  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    e.preventDefault();
    var email = document.getElementById('email');
    var tel = document.getElementById('telefone');
    var emailOk = validar(email, document.getElementById('erro-email'),
      /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email.value.trim()) ? '' : 'Informe um e-mail completo, como nome@empresa.com.br.');
    var digitos = tel.value.replace(/\D/g, '');
    var telOk = validar(tel, document.getElementById('erro-telefone'),
      (digitos.length === 10 || digitos.length === 11) ? '' : 'Informe o DDD e o número, como (11) 91234-5678.');
    var resumo = document.getElementById('resumo-erros');
    var lista = document.getElementById('lista-erros');
    if (!emailOk || !telOk) {
      lista.innerHTML = '';
      if (!emailOk) lista.insertAdjacentHTML('beforeend', '<li><a href="#email">E-mail corporativo</a></li>');
      if (!telOk) lista.insertAdjacentHTML('beforeend', '<li><a href="#telefone">Telefone celular</a></li>');
      resumo.hidden = false;
      document.title = 'Erro: Configurações da conta - TransLog Cargas';
      resumo.focus();
      return;
    }
    resumo.hidden = true;
    document.title = 'Configurações da conta - TransLog Cargas';
    // Enviar ao servidor aqui; anunciar "Perfil salvo." somente após resposta de sucesso.
  });

  document.getElementById('form-prefs').addEventListener('submit', function (e) {
    e.preventDefault();
    // Enviar ao servidor aqui; exibir o banner somente após resposta de sucesso.
    document.getElementById('banner-sucesso').hidden = false;
    anunciar('Preferências de notificação salvas.');
  });

  document.getElementById('form-excluir').addEventListener('submit', function (e) {
    e.preventDefault();
    var campo = document.getElementById('confirma-excluir');
    var erro = document.getElementById('erro-confirma');
    if (campo.value.trim() !== 'EXCLUIR') {
      erro.hidden = false;
      campo.setAttribute('aria-invalid', 'true');
      campo.focus();
      return;
    }
    // Enviar a exclusão ao servidor aqui.
  });
})();
