(function () {
  var disparador = null;
  function abrir(id, origem) {
    var fundo = document.getElementById(id);
    disparador = origem;
    fundo.hidden = false;
    fundo.querySelector('[data-foco-inicial]').focus();
  }
  function fechar(fundo) {
    fundo.hidden = true;
    if (disparador) { disparador.focus(); disparador = null; }
  }
  document.querySelectorAll('[data-abrir]').forEach(function (b) {
    b.addEventListener('click', function () { abrir(b.getAttribute('data-abrir'), b); });
  });
  document.querySelectorAll('[data-fechar]').forEach(function (b) {
    b.addEventListener('click', function () { fechar(b.closest('[data-modal]')); });
  });
  document.querySelectorAll('[data-modal]').forEach(function (f) {
    f.addEventListener('keydown', function (e) {
      if (e.key === 'Escape') { fechar(f); return; }
      if (e.key !== 'Tab') return;
      var foc = f.querySelectorAll('button:not([disabled])');
      var primeiro = foc[0], ultimo = foc[foc.length - 1];
      if (e.shiftKey && document.activeElement === primeiro) { e.preventDefault(); ultimo.focus(); }
      else if (!e.shiftKey && document.activeElement === ultimo) { e.preventDefault(); primeiro.focus(); }
    });
  });
  document.getElementById('btn-dispensar').addEventListener('click', function () {
    document.getElementById('banner-sucesso').hidden = true;
    var h = document.getElementById('h-pref');
    h.setAttribute('tabindex', '-1');
    h.focus();
  });
  document.getElementById('form-perfil').addEventListener('submit', function (e) {
    if (!this.checkValidity()) {
      e.preventDefault();
      document.getElementById('resumo-erros').focus();
    }
  });
})();
@@ FIM

